function applyRegionEnrichment(locations) {
    for (const [countryName, country] of Object.entries(locations)) {
        if (Object.keys(country.regions).length > 0) continue;
        const enriched = countryRegionsEnrichment[window.currentLang || "ru"]?.[countryName]
            || countryRegionsEnrichment["ru"]?.[countryName];
        if (enriched) country.regions = JSON.parse(JSON.stringify(enriched));
    }
    return locations;
}